'use strict';

const D=window.AETHERIS_DATA;
const $=id=>document.getElementById(id);
const qsa=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const ALL_SKILLS=D.skills.flatMap(g=>g.items.map(name=>({name,attr:g.attr,group:g.group})));
const SKILL_ATTR=Object.fromEntries(ALL_SKILLS.map(s=>[s.name,s.attr]));
const REGIONAL_PROFESSION_MAP={};
Object.entries(D.regionalProfessions||{}).forEach(([region,items])=>items.forEach(item=>REGIONAL_PROFESSION_MAP[item.name]={...item,region}));

function officialProfessionFromLegacy(name){
  if(D.professions[name])return name;
  const regional=REGIONAL_PROFESSION_MAP[name];
  return regional?.base&&D.professions[regional.base]?regional.base:'';
}
function resolveProfession(name){const official=officialProfessionFromLegacy(name);return official?{...D.professions[official],name:official,base:official,region:'Geral'}:null}
function updateProfessionOptions(){
  const general=Object.keys(D.professions);
  $('f-profissao').innerHTML='<option value="">— Selecione —</option>'+general.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');
  if(state.profession&&!D.professions[state.profession])state.profession=officialProfessionFromLegacy(state.profession);
  $('f-profissao').value=state.profession||'';
}
function defaultState(){
  const training={};ALL_SKILLS.forEach(s=>training[s.name]=0);
  return {schemaVersion:3,level:1,attrs:{forca:1,destreza:1,intelecto:1,vontade:1,fe:1},race:'',avarisLineage:'alada',profession:'',path:'',training,
    talents:[],criticalChoice:'fisico',armorTrainingChoice:'',specialistSkills:['',''],capstone:'',masterArcanePowerId:'',
    pvLoss:0,peSpent:0,soulLoss:0,patron:'',favor:2,learnedBlessings:[],corruption:0,corruptionManifestation:'',corruptionPenalty:'',corruptionBlessingMode:'cost',pactType:'',
    powers:[],armor:'Sem armadura',shield:false,weapon:'Desarmado',slotsUsed:0,consumables:[],conditions:[],deathSuccess:0,deathFail:0,reputation:[],avatarData:''};
}
let state=defaultState(),currentSheetId=null,masterViewing=false,migrationNotice='',sheetRows=[];
const LEVEL_GAINS={1:'Raça, Profissão, Caminho, 8 pontos de Treino e escolhas iniciais.',2:'+3 PV, +2 PE e 1 Talento.',3:'+3 PV, +2 PE; acesso a poder Intermediário ou nova bênção.',4:'+3 PV, +2 PE, +2 pontos de Treino; primeira Maestria possível.',5:'+3 PV, +2 PE, +1 Atributo e 1 Talento.',6:'+3 PV, +2 PE; acesso a poder Avançado e melhoria de Profissão.',7:'+3 PV, +2 PE; nova bênção, pacto ou poder e +1 Favor máximo.',8:'+3 PV, +2 PE, +2 pontos de Treino; segunda Maestria possível.',9:'+3 PV, +2 PE; acesso a poder Supremo e 1 Talento.',10:'+3 PV, +2 PE, +1 Atributo e uma Capstone.'};

function fillSelect(el,values,placeholder='— Selecione —',mapper=v=>({value:v,label:v})){el.innerHTML=`<option value="">${esc(placeholder)}</option>`+values.map(v=>{const m=mapper(v);return `<option value="${esc(m.value)}">${esc(m.label)}</option>`}).join('')}
function cssId(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function toggleArray(arr,value,checked){const i=arr.indexOf(value);if(checked&&i<0)arr.push(value);if(!checked&&i>=0)arr.splice(i,1)}
function showBox(id,text,show){const el=$(id);el.textContent=text;el.classList.toggle('hidden',!show)}
function statBonus(source,key){return source?.statBonus?.[key]||0}
function profession(){return resolveProfession(state.profession)}function race(){return D.races[state.race]||null}
function armor(){return D.armors.find(a=>a.name===state.armor)||D.armors[0]}function weapon(){return D.weapons.find(w=>w.name===state.weapon)||D.weapons[0]}
function hasTalent(id){return state.talents.includes(id)}function talentCalc(key){return D.talents.filter(t=>hasTalent(t.id)).reduce((sum,t)=>sum+(t.calc?.[key]||0),0)}
function attrPool(){return 12+(state.level>=5?1:0)+(state.level>=10?1:0)}function attrCap(){return state.level>=10?6:state.level>=5?5:4}function attrSpent(){return D.attributes.reduce((s,a)=>s+(state.attrs[a]||0),0)}
function talentSlots(){return [2,5,9].filter(l=>state.level>=l).length+(state.path==='Livre'?1:0)}
function masterySlots(){return hasTalent('maestria')?((state.level>=4?1:0)+(state.level>=8?1:0)):0}
function trainingPool(){return 8+(state.level>=4?2:0)+(state.level>=8?2:0)+(race()?.trainingBonus||0)}function trainingSpent(){return Object.values(state.training).reduce((a,b)=>a+(Number(b)||0),0)}function masteryUsed(){return Object.values(state.training).filter(v=>Number(v)>=3).length}
function professionSkillBonus(name){return profession()?.skillBonus?.[name]||0}function favorSkillBonus(name){return name==='Rituais'&&state.patron&&state.favor>=4?1:0}function raceSkillBonus(){return 0}
function specialistBonus(name){if(!hasTalent('especialista'))return 0;const chosen=(state.specialistSkills||[]).filter(Boolean);return chosen.includes(name)&&(state.training[name]||0)<2?1:0}
function ritualistBonus(name){return hasTalent('ritualista')&&name==='Rituais'?1:0}
function armorTrainedForCurrent(){return hasTalent('armadura_treinada')&&state.armorTrainingChoice===state.armor}
function armorSkillModifier(name){if(name==='Furtividade'&&state.armor==='Média'&&!armorTrainedForCurrent())return -1;return 0}
function otherSkillBonus(name){return favorSkillBonus(name)+specialistBonus(name)+ritualistBonus(name)+armorSkillModifier(name)}
function effectiveTraining(name){return (state.training[name]||0)+specialistBonus(name)}
function skillTotal(name){const a=SKILL_ATTR[name];return (state.attrs[a]||0)+raceSkillBonus(name)+professionSkillBonus(name)+(state.training[name]||0)+otherSkillBonus(name)}
function passiveSkill(name){return 10+skillTotal(name)+(name==='Percepção'?talentCalc('passivePerception'):0)}
function inventoryCapacity(){return 8+(state.attrs.forca||0)*2}function isEncumbered(){return state.slotsUsed>inventoryCapacity()}
function pvMax(){return Math.max(1,12+state.attrs.forca*4+state.level*3+statBonus(race(),'pv')+statBonus(profession(),'pv')+talentCalc('pv'))}
function peMax(){return Math.max(1,8+state.attrs.vontade*2+state.attrs.fe*3+state.level*2+statBonus(race(),'pe')+statBonus(profession(),'pe')+talentCalc('pe'))}
function soulMax(){return Math.max(1,5+state.attrs.vontade+state.attrs.fe+talentCalc('soul'))}
function defense(){let v=10+state.attrs.destreza*2+armor().defense+(state.shield?1:0)+statBonus(race(),'defesa');if(state.race==='feliri'&&state.armor!=='Pesada')v+=1;return v}
function movement(){let armMove=armor().movement;if(armorTrainedForCurrent())armMove=0;let v=6+armMove+talentCalc('movement');if(state.race==='avaris'&&state.avarisLineage==='nao-alada')v+=2;if(isEncumbered())v-=2;return Math.max(0,v)}
function corruptionResistance(){return state.attrs.vontade+statBonus(race(),'rescorr')}function favorMax(){return 5+(state.level>=7?1:0)+talentCalc('favorMax')}
function currentPV(){return clamp(pvMax()-state.pvLoss,0,pvMax())}function currentPE(){return clamp(peMax()-state.peSpent,0,peMax())}function currentSoul(){return clamp(soulMax()-state.soulLoss,0,soulMax())}

function initStatic(){
  fillSelect($('f-regiao'),D.regions);fillSelect($('f-raca'),Object.keys(D.races),'— Selecione —',k=>({value:k,label:D.races[k].label}));updateProfessionOptions();fillSelect($('f-caminho'),Object.keys(D.paths));fillSelect($('f-patrono'),Object.keys(D.blessings),'— Sem patrono —');fillSelect($('f-capstone'),D.capstones,'— Nenhuma —',c=>({value:c.id,label:c.name}));fillSelect($('f-armadura'),D.armors,'',a=>({value:a.name,label:`${a.name} (+${a.defense} Defesa)`}));fillSelect($('f-arma'),D.weapons,'',w=>({value:w.name,label:`${w.name} — ${w.damage}`}));
  buildAttrGrid();buildSkillsTable();buildTalents();buildConditions();buildConsumables();buildDeathTracks();bindEvents();renderAll();checkSession();
}
function buildAttrGrid(){$('attr-grid').innerHTML=D.attributes.map(a=>`<div class="attr-card"><div class="name">${esc(D.attributeLabels[a])}</div><div class="row"><button class="stepper no-print" data-attr="${a}" data-dir="-1">−</button><span class="value" id="attr-${a}">1</span><button class="stepper no-print" data-attr="${a}" data-dir="1">+</button></div></div>`).join('')}
function buildSkillsTable(){let html='';D.skills.forEach(group=>{html+=`<tr class="group-row"><td colspan="8">${esc(group.group)}</td></tr>`;group.items.forEach(name=>{const id=cssId(name);html+=`<tr><td>${esc(name)}</td><td class="center" id="sk-attr-${id}">0</td><td class="center" id="sk-race-${id}">+0</td><td class="center" id="sk-prof-${id}">+0</td><td class="center" id="sk-other-${id}">+0</td><td><div class="train-controls"><button class="stepper no-print" data-skill="${esc(name)}" data-dir="-1">−</button><span id="sk-train-${id}">0</span><button class="stepper no-print" data-skill="${esc(name)}" data-dir="1">+</button></div></td><td class="center"><span class="total-pill" id="sk-total-${id}">0</span></td><td class="center" id="sk-passive-${id}">10</td></tr>`})});$('skills-body').innerHTML=html}
function buildTalents(){$('talents-grid').innerHTML=D.talents.map(t=>`<label class="check-card" id="talent-card-${t.id}"><input type="checkbox" data-talent="${t.id}"><span><span class="name">${esc(t.name)}</span><span class="desc">${esc(t.effect)}</span></span></label>`).join('')}
function buildConditions(){$('conditions-grid').innerHTML=D.conditions.map(c=>`<label class="check-card"><input type="checkbox" data-condition="${c.id}"><span><span class="name">${esc(c.name)}</span><span class="desc">${esc(c.effect)}</span></span></label>`).join('')}
function buildConsumables(){$('consumables-grid').innerHTML=D.consumables.map(c=>`<label class="check-card"><input type="checkbox" data-consumable="${esc(c.name)}"><span><span class="name">${esc(c.name)}</span><span class="desc">${esc(c.effect)}</span></span></label>`).join('')}
function buildDeathTracks(){$('death-success').innerHTML=[1,2,3].map(i=>`<button class="death-dot success no-print" data-death="success" data-value="${i}"></button>`).join('');$('death-fail').innerHTML=[1,2,3].map(i=>`<button class="death-dot fail no-print" data-death="fail" data-value="${i}"></button>`).join('')}

function bindEvents(){
  $('login-btn').addEventListener('click',doLogin);$('register-btn').addEventListener('click',doRegister);$('logout-btn').addEventListener('click',doLogout);$('auth-password').addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()});
  $('master-toggle-btn').addEventListener('click',toggleMasterPanel);$('exit-master-btn').addEventListener('click',exitMasterView);
  $('save-btn').addEventListener('click',saveCurrentSheet);$('load-btn').addEventListener('click',loadSelectedSheet);$('delete-btn').addEventListener('click',deleteSelectedSheet);$('new-btn').addEventListener('click',newSheet);
  $('library-btn').addEventListener('click',()=>openLibrary());$('library-close-btn').addEventListener('click',closeLibrary);$('library-new-btn').addEventListener('click',()=>{closeLibrary();newSheet()});qsa('[data-close-library]').forEach(x=>x.addEventListener('click',closeLibrary));
  qsa('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
  $('export-btn').addEventListener('click',exportSheet);$('import-btn').addEventListener('click',()=>$('import-file').click());$('import-file').addEventListener('change',importSheet);
  $('avatar-upload-btn').addEventListener('click',()=>$('avatar-file').click());$('avatar-file').addEventListener('change',handleAvatarUpload);$('avatar-remove-btn').addEventListener('click',()=>{state.avatarData='';renderAvatar()});
  $('level-up-btn').addEventListener('click',()=>{state.level=clamp(state.level+1,1,10);renderAll()});$('level-down-btn').addEventListener('click',()=>{state.level=clamp(state.level-1,1,10);renderAll()});
  $('f-regiao').addEventListener('change',()=>renderAll());$('f-raca').addEventListener('change',e=>{state.race=e.target.value;renderAll()});$('f-avaris-lineage').addEventListener('change',e=>{state.avarisLineage=e.target.value;renderAll()});$('f-profissao').addEventListener('change',e=>{state.profession=e.target.value;renderAll()});
  $('f-caminho').addEventListener('change',e=>{const old=state.path;state.path=e.target.value;if(state.path==='Pactuário'&&old!==state.path&&state.corruption===0)state.corruption=1;renderAll()});
  $('f-capstone').addEventListener('change',e=>{state.capstone=e.target.value;renderAll()});$('f-patrono').addEventListener('change',e=>{state.patron=e.target.value;state.learnedBlessings=state.learnedBlessings.filter(n=>(D.blessings[state.patron]?.skills||[]).some(s=>s.nome===n));renderAll()});$('f-favor').addEventListener('input',e=>{state.favor=Number(e.target.value);renderAll()});
  $('f-corruption-blessing-mode').addEventListener('change',e=>{state.corruptionBlessingMode=e.target.value;renderBlessings()});$('f-pact-type').addEventListener('change',e=>{state.pactType=e.target.value;renderValidation()});
  $('f-armadura').addEventListener('change',e=>{state.armor=e.target.value;renderAll()});$('f-escudo').addEventListener('change',e=>{state.shield=e.target.value==='sim';renderAll()});$('f-arma').addEventListener('change',e=>{state.weapon=e.target.value;renderAll()});$('f-slots-used').addEventListener('input',e=>{state.slotsUsed=Math.max(0,Number(e.target.value)||0);renderAll()});
  $('add-power-btn').addEventListener('click',()=>{state.powers.push(newPower());renderPowers();renderValidation()});$('add-reputation-btn').addEventListener('click',()=>{state.reputation.push({name:'',value:0});renderReputation()});
  $('pause-rest').addEventListener('click',pauseRest);$('short-rest').addEventListener('click',shortRest);$('long-rest').addEventListener('click',longRest);
  ['f-nome','f-regiao','f-conceito','f-objetivo','f-vinculo','p-marca'].forEach(id=>$(id).addEventListener('input',()=>{renderCharacterSummary();renderValidation()}));
  document.addEventListener('click',e=>{const attr=e.target.dataset.attr;if(attr){stepAttr(attr,Number(e.target.dataset.dir));return}const skill=e.target.dataset.skill;if(skill){stepTraining(skill,Number(e.target.dataset.dir));return}if(e.target.dataset.adjust){adjustCurrent(e.target.dataset.adjust,Number(e.target.dataset.dir));return}if(e.target.dataset.counter==='corruption'){adjustCorruption(Number(e.target.dataset.dir));return}if(e.target.dataset.death){const key=e.target.dataset.death==='success'?'deathSuccess':'deathFail',val=Number(e.target.dataset.value);state[key]=state[key]===val?0:val;renderDeathTracks();return}});
  document.addEventListener('change',e=>{if(e.target.dataset.talent){toggleArray(state.talents,e.target.dataset.talent,e.target.checked);if(e.target.dataset.talent==='critico_aprimorado'&&!e.target.checked)state.criticalChoice='fisico';renderAll();return}if(e.target.dataset.condition){toggleArray(state.conditions,e.target.dataset.condition,e.target.checked);renderConditions();return}if(e.target.dataset.consumable){toggleArray(state.consumables,e.target.dataset.consumable,e.target.checked);renderConsumables();return}if(e.target.dataset.blessing){toggleArray(state.learnedBlessings,e.target.dataset.blessing,e.target.checked);renderBlessings();renderValidation();return}});
  ['f-corruption-manifestation','f-corruption-penalty'].forEach(id=>$(id).addEventListener('input',()=>{state.corruptionManifestation=$('f-corruption-manifestation').value;state.corruptionPenalty=$('f-corruption-penalty').value}));
}
function switchTab(name){qsa('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));qsa('.tab-page').forEach(p=>p.classList.toggle('active',p.id===`tab-${name}`));window.scrollTo({top:Math.max(0,$('app-content').offsetTop),behavior:'smooth'})}
function openLibrary(){refreshSheetDropdown(currentSheetId,true);$('character-library').classList.remove('hidden')}function closeLibrary(){$('character-library').classList.add('hidden')}

function renderAll(){
  state.level=clamp(Number(state.level)||1,1,10);state.attrs={...defaultState().attrs,...state.attrs};state.training={...defaultState().training,...state.training};state.specialistSkills=Array.isArray(state.specialistSkills)?[state.specialistSkills[0]||'',state.specialistSkills[1]||'']:['',''];
  state.pvLoss=clamp(Number(state.pvLoss)||0,0,pvMax());state.peSpent=clamp(Number(state.peSpent)||0,0,peMax());state.soulLoss=clamp(Number(state.soulLoss)||0,0,soulMax());state.favor=clamp(Number(state.favor)||0,0,favorMax());state.corruption=clamp(Number(state.corruption)||0,0,10);
  updateProfessionOptions();$('f-raca').value=state.race;$('f-avaris-lineage').value=state.avarisLineage;$('f-profissao').value=state.profession;$('f-caminho').value=state.path;$('f-capstone').value=state.capstone;$('f-patrono').value=state.patron;$('f-favor').max=favorMax();$('f-favor').value=state.favor;$('f-armadura').value=state.armor;$('f-escudo').value=state.shield?'sim':'nao';$('f-arma').value=state.weapon;$('f-slots-used').value=state.slotsUsed;$('f-corruption-manifestation').value=state.corruptionManifestation||'';$('f-corruption-penalty').value=state.corruptionPenalty||'';$('f-corruption-blessing-mode').value=state.corruptionBlessingMode||'cost';$('f-pact-type').value=state.pactType||'';
  renderLevel();renderRaceProfessionPath();renderAttributes();renderSkills();renderTalents();renderStats();renderBlessings();renderCorruption();renderPowers();renderEquipment();renderConditions();renderDeathTracks();renderReputation();renderAvatar();renderCharacterSummary();renderValidation();
}
function renderLevel(){$('level-badge').textContent=state.level;$('level-up-btn').disabled=state.level>=10;$('level-down-btn').disabled=state.level<=1;$('progression-strip').innerHTML=Array.from({length:10},(_,i)=>{const n=i+1;return `<div class="level-dot ${n<=state.level?'active':''} ${n===state.level?'current':''}" title="${esc(LEVEL_GAINS[n])}">${n}</div>`}).join('');$('level-gain-info').innerHTML=`<strong>Nível ${state.level}:</strong> ${esc(LEVEL_GAINS[state.level])}`}
function renderRaceProfessionPath(){$('avaris-lineage-wrap').classList.toggle('hidden',state.race!=='avaris');const r=race();$('race-info').innerHTML=r?`<strong>${esc(r.label)}</strong><br>${esc(r.summary)}<br>${r.traits.map(t=>`<span class="tag">${esc(t.name)}</span> ${esc(t.effect)}`).join('<br>')}`:'Selecione uma raça.';const p=profession();$('profession-info').innerHTML=p?`<strong>${esc(p.name)}</strong><br>${esc(p.summary)}<br><span class="tag">Talento profissional</span> ${esc(p.talent)}<br><span class="tag">Equipamento inicial</span> ${esc(p.equipment)}`:'Selecione uma das profissões oficiais do Grimório.';const path=D.paths[state.path];$('path-info').innerHTML=path?`<strong>${esc(state.path)}</strong><br>${esc(path.benefit)}<br><span class="tag tag-red">Limitação</span> ${esc(path.limit)}`:'Selecione um Caminho espiritual.'}
function renderAttributes(){D.attributes.forEach(a=>{$(`attr-${a}`).textContent=state.attrs[a];qsa(`[data-attr="${a}"]`).forEach(b=>{const dir=Number(b.dataset.dir);b.disabled=dir<0?state.attrs[a]<=1:state.attrs[a]>=attrCap()||attrSpent()>=attrPool()})});$('attr-spent').textContent=attrSpent();$('attr-pool').textContent=attrPool();$('attr-cap').textContent=attrCap();const warnings=[];if(attrSpent()!==attrPool())warnings.push(`Distribua exatamente ${attrPool()} pontos; diferença de ${Math.abs(attrPool()-attrSpent())}.`);if(D.attributes.some(a=>state.attrs[a]<1||state.attrs[a]>attrCap()))warnings.push('Há atributo fora do limite atual.');showBox('attr-warning',warnings.join(' '),warnings.length>0)}
function stepAttr(a,dir){const next=state.attrs[a]+dir;if(next<1||next>attrCap())return;if(dir>0&&attrSpent()>=attrPool())return;state.attrs[a]=next;renderAll()}
function renderSkills(){ALL_SKILLS.forEach(s=>{const id=cssId(s.name),ab=state.attrs[s.attr]||0,rb=raceSkillBonus(s.name),pb=professionSkillBonus(s.name),ob=otherSkillBonus(s.name),tr=state.training[s.name]||0,total=skillTotal(s.name);$(`sk-attr-${id}`).textContent=ab;$(`sk-race-${id}`).textContent=`${rb>=0?'+':''}${rb}`;$(`sk-prof-${id}`).textContent=`${pb>=0?'+':''}${pb}`;$(`sk-other-${id}`).textContent=`${ob>=0?'+':''}${ob}`;$(`sk-train-${id}`).innerHTML=`${tr}${tr>=3?'<span class="mastery-mark">M</span>':''}`;$(`sk-total-${id}`).textContent=total;$(`sk-passive-${id}`).textContent=passiveSkill(s.name);qsa(`[data-skill="${CSS.escape(s.name)}"]`).forEach(b=>{const d=Number(b.dataset.dir);b.disabled=d<0?tr<=0:(tr>=3||trainingSpent()>=trainingPool()||(tr===2&&masteryUsed()>=masterySlots()))})});$('train-spent').textContent=trainingSpent();$('train-pool').textContent=trainingPool();$('mastery-used').textContent=masteryUsed();$('mastery-slots').textContent=masterySlots();const warnings=[];if(trainingSpent()>trainingPool())warnings.push(`Treino excede o limite em ${trainingSpent()-trainingPool()} ponto(s).`);if(masteryUsed()>masterySlots())warnings.push('Há mais perícias em Maestria do que permitido.');if(hasTalent('especialista')){const sp=state.specialistSkills.filter(Boolean);if(sp.length!==2||sp[0]===sp[1])warnings.push('Especialista exige duas perícias diferentes.');if(sp.some(n=>(state.training[n]||0)>=2))warnings.push('Especialista deve respeitar o limite de Treino; escolha perícias com Treino 0 ou 1.')}showBox('training-warning',warnings.join(' '),warnings.length>0)}
function stepTraining(name,dir){const cur=state.training[name]||0,next=cur+dir;if(next<0||next>3)return;if(dir>0&&trainingSpent()>=trainingPool())return;if(next===3&&masteryUsed()>=masterySlots())return;state.training[name]=next;renderAll()}
function renderTalents(){qsa('[data-talent]').forEach(cb=>{cb.checked=hasTalent(cb.dataset.talent);cb.closest('.check-card').classList.toggle('active',cb.checked)});$('talent-count').textContent=state.talents.length;$('talent-slots').textContent=talentSlots();qsa('[data-talent]').forEach(cb=>{if(!cb.checked)cb.disabled=state.talents.length>=talentSlots()});$('f-capstone').disabled=state.level<10;const cap=D.capstones.find(c=>c.id===state.capstone);$('capstone-info').innerHTML=state.level<10?'Capstones são liberadas no nível 10.':cap?`<strong>${esc(cap.name)}</strong><br>${esc(cap.effect)}`:'Escolha uma Capstone.';renderTalentOptions()}
function skillOptions(value){return '<option value="">— Selecione —</option>'+ALL_SKILLS.map(s=>`<option ${s.name===value?'selected':''}>${esc(s.name)}</option>`).join('')}
function renderTalentOptions(){const rows=[];if(hasTalent('critico_aprimorado'))rows.push(`<div class="field"><label>Crítico Aprimorado</label><select id="talent-critical-choice"><option value="fisico" ${state.criticalChoice==='fisico'?'selected':''}>Físico</option><option value="magico" ${state.criticalChoice==='magico'?'selected':''}>Mágico</option></select></div>`);if(hasTalent('armadura_treinada'))rows.push(`<div class="field"><label>Armadura Treinada — categoria</label><select id="talent-armor-choice"><option value="">— Selecione —</option>${D.armors.filter(a=>a.name!=='Sem armadura').map(a=>`<option ${state.armorTrainingChoice===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div>`);if(hasTalent('especialista')){rows.push(`<div class="field"><label>Especialista — perícia 1</label><select id="specialist-skill-1">${skillOptions(state.specialistSkills[0])}</select></div>`);rows.push(`<div class="field"><label>Especialista — perícia 2</label><select id="specialist-skill-2">${skillOptions(state.specialistSkills[1])}</select></div>`)}if(state.level>=10&&state.capstone==='mestre_arcano'){const advanced=state.powers.filter(p=>p.tier==='Avançado');rows.push(`<div class="field"><label>Mestre Arcano — poder Avançado</label><select id="master-arcane-power"><option value="">— Selecione —</option>${advanced.map(p=>`<option value="${esc(p.id)}" ${String(state.masterArcanePowerId)===String(p.id)?'selected':''}>${esc(p.name||'Poder sem nome')}</option>`).join('')}</select></div>`)}$('talent-options').innerHTML=rows.join('');$('talent-critical-choice')?.addEventListener('change',e=>{state.criticalChoice=e.target.value;renderStats()});$('talent-armor-choice')?.addEventListener('change',e=>{state.armorTrainingChoice=e.target.value;renderAll()});$('specialist-skill-1')?.addEventListener('change',e=>{state.specialistSkills[0]=e.target.value;renderAll()});$('specialist-skill-2')?.addEventListener('change',e=>{state.specialistSkills[1]=e.target.value;renderAll()});$('master-arcane-power')?.addEventListener('change',e=>{state.masterArcanePowerId=e.target.value;renderPowers()})}
function renderStats(){const phys=hasTalent('critico_aprimorado')&&state.criticalChoice==='fisico',mag=hasTalent('critico_aprimorado')&&state.criticalChoice==='magico';const heavyStealth=state.armor==='Pesada'&&!armorTrainedForCurrent()?' Desvantagem em Furtividade.':'';const stats=[['Defesa',defense(),`10 + Destreza × 2 + armadura${state.shield?' + escudo':''}.`],['Movimento',`${movement()}m`,state.race==='avaris'&&state.avarisLineage==='alada'?(state.armor==='Pesada'?'Voo impedido por armadura pesada.':'Voo 6m; após o primeiro turno, 1 PE/turno.'):`Base 6m, ajustado por raça, talento, armadura e carga.${heavyStealth}`],['Resist. à Corrupção',corruptionResistance(),'Vontade + bônus de Raça + bônus espirituais.'],['Iniciativa',`+${skillTotal('Iniciativa')}`,'Total da perícia Iniciativa.'],['Percepção Passiva',passiveSkill('Percepção'),'10 + Total de Percepção.'],['Crítico Físico',phys?'19–20':'20','Crítico Aprimorado escolhe físico ou mágico.'],['Crítico Mágico',mag?'19–20':'20','Crítico Aprimorado escolhe físico ou mágico.'],['Capacidade',`${inventoryCapacity()} espaços`,isEncumbered()?'Sobrecarregado: -2m e desvantagem em Atletismo/Acrobacia.':'Sem penalidade de carga.']];$('stat-grid').innerHTML=stats.map(([l,v,s])=>`<div class="stat-card"><div class="label">${esc(l)}</div><div class="value">${esc(v)}</div><div class="sub">${esc(s)}</div></div>`).join('');const pv=pvMax(),pe=peMax(),so=soulMax(),cp=currentPV(),ce=currentPE(),cs=currentSoul();$('pv-max').textContent=pv;$('pv-current').textContent=cp;$('pv-bar').style.width=`${pv?cp/pv*100:0}%`;$('pe-max').textContent=pe;$('pe-current').textContent=ce;$('pe-bar').style.width=`${pe?ce/pe*100:0}%`;$('soul-max').textContent=so;$('soul-current').textContent=cs;$('soul-bar').style.width=`${so?cs/so*100:0}%`}
function adjustCurrent(kind,dir){if(kind==='pv')state.pvLoss=clamp(state.pvLoss-dir,0,pvMax());if(kind==='pe')state.peSpent=clamp(state.peSpent-dir,0,peMax());if(kind==='soul')state.soulLoss=clamp(state.soulLoss-dir,0,soulMax());renderStats()}function rollDie(sides){return 1+Math.floor(Math.random()*sides)}function pauseRest(){const recovered=Math.min(currentPE()<peMax()?state.attrs.vontade:0,state.peSpent);state.peSpent=Math.max(0,state.peSpent-recovered);setStatus(`Pausa: ${recovered} PE recuperado(s).`);renderStats()}function shortRest(){const pvRec=rollDie(6)+state.attrs.forca,peRec=Math.ceil(peMax()/2);state.pvLoss=Math.max(0,state.pvLoss-pvRec);state.peSpent=Math.max(0,state.peSpent-peRec);setStatus(`Descanso curto: ${pvRec} PV e até ${peRec} PE recuperados.`);renderStats()}function longRest(){state.peSpent=0;const safe=$('safe-shelter').checked;if(safe)state.pvLoss=0;else state.pvLoss=Math.max(0,state.pvLoss-Math.ceil(pvMax()/2));setStatus(`Descanso longo: PE restaurado e ${safe?'todo PV':'metade do PV máximo'} recuperado.`);renderStats()}
function favorState(){return [{n:0,name:'Rompido',effect:'Não usa bênçãos.'},{n:1,name:'Distante',effect:'Bênçãos custam +1 PE.'},{n:2,name:'Reconhecido',effect:'Funcionamento normal.'},{n:3,name:'Consagrado',effect:'Uma vez por cena, reduza 1 PE de uma bênção.'},{n:4,name:'Eleito',effect:'+1 em Rituais ligados ao patrono.'},{n:5,name:'Avatar parcial',effect:'Milagre Menor sem custo, uma vez por sessão.'}].find(x=>x.n===Math.min(state.favor,5))}
function blessingEffectiveCost(s){if(s.custo===0)return 0;let eff=s.custo;if(state.favor===1)eff++;if(state.corruption>=6&&state.corruption<=8&&state.corruptionBlessingMode==='cost')eff++;return eff}
function renderBlessings(){const fm=favorMax();if(state.favor>fm)state.favor=fm;$('f-favor').max=fm;$('f-favor').value=state.favor;const fs=favorState();$('favor-badge').innerHTML=`${state.favor}<small style="display:block;font:10px var(--body);color:var(--muted)">${esc(fs.name)}</small>`;$('corruption-blessing-wrap').classList.toggle('hidden',state.corruption<6||state.corruption>8);const g=D.blessings[state.patron];$('god-info').innerHTML=g?`<strong>${esc(state.patron)}</strong><br><span class="tag">Domínios</span> ${esc(g.dominios)}<br><span class="tag tag-red">Corrupção típica</span> ${esc(g.corrupcao)}<br><span class="tag tag-teal">Favor ${state.favor}</span> ${esc(fs.effect)}`:'Escolha uma divindade patrona para ver domínios, corrupção típica e bênçãos.';if(!g){$('blessings-grid').innerHTML='';$('blessing-guidance').textContent='Devotos iniciam com Favor 2 e duas bênçãos de custo até 5.';return}$('blessings-grid').innerHTML=g.skills.map(s=>{const learned=state.learnedBlessings.includes(s.nome),blocked=state.favor===0,eff=blessingEffectiveCost(s);return `<label class="blessing-card ${learned?'learned':''}"><input type="checkbox" data-blessing="${esc(s.nome)}" ${learned?'checked':''}><span><span class="blessing-name">${esc(s.nome)}</span><span class="blessing-meta">${esc(s.tipo)} · ${esc(s.acao)} · ${esc(s.alcance)} · Resist.: ${esc(s.resistencia||'-')}</span><span class="blessing-effect">${esc(s.efeito)}</span></span><span class="blessing-cost">${blocked?'Rompido':`${eff} PE`}</span></label>`}).join('');const learned=g.skills.filter(s=>state.learnedBlessings.includes(s.nome)),initialOk=learned.filter(s=>s.custo<=5).length;let guidance=`Aprendidas: <strong>${learned.length}</strong>. `;if(state.path==='Devoto')guidance+=state.level===1?`No nível 1: duas bênçãos de custo-base até 5 (${initialOk}/2 compatíveis).`:'Novas bênçãos podem vir das escolhas de progressão e talentos.';else if(state.path==='Livre')guidance+='O Caminho Livre não recebe milagres sem vínculo posterior.';else if(state.path==='Pactuário')guidance+='Bênçãos podem sofrer +1 PE ou teste de Favor quando a Corrupção chega a 6–8.';else guidance+='Escolha um Caminho para validar as escolhas iniciais.';$('blessing-guidance').innerHTML=guidance}
function adjustCorruption(dir){const old=state.corruption;state.corruption=clamp(old+dir,0,10);if(dir>0&&old>=9&&state.corruption>old)state.soulLoss=clamp(state.soulLoss+1,0,soulMax());renderAll()}
function renderCorruption(){$('corr-current').textContent=state.corruption;$('corr-bar').style.width=`${state.corruption*10}%`;let st,eff;if(state.corruption<=2){st='Estável';eff='Sinais discretos; sem penalidade permanente.'}else if(state.corruption<=5){st='Marcado';eff='Manifestação menor e -1 em um tipo específico de resistência.'}else if(state.corruption<=8){st='Deformado';eff='Manifestação maior; bênçãos custam +1 PE ou exigem teste de Favor.'}else if(state.corruption===9){st='À beira';eff='Toda nova Corrupção também reduz 1 Integridade da Alma.'}else{st='Virada';eff='Perde o Caminho atual e sofre transformação definida com o mestre.'}$('corruption-info').innerHTML=`<strong>${st}</strong><br>${eff}${state.path==='Pactuário'&&state.corruption<1?'<br><span class="tag tag-red">Pactuário deve iniciar com 1 Corrupção.</span>':''}`}

function newPower(){return {id:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),name:'',source:state.path==='Pactuário'?'Abissal':'Arcano',tier:'Comum',keyAttr:'intelecto',skill:'Ocultismo',form:'Ataque direto',damage:['Corte'],effects:[],upgrades:[],limitations:[],description:'',signature:false}}
function powerCost(p){let total=D.powerForms.find(x=>x.name===p.form)?.cost||0;(p.damage||[]).forEach(n=>total+=(D.damageTypes.find(x=>x.name===n)?.cost||0));(p.effects||[]).forEach(n=>total+=(D.debuffs.find(x=>x.name===n)?.cost||0));let extraDie=0;(p.upgrades||[]).forEach(n=>{const u=D.upgrades.find(x=>x.name===n);if(!u)return;if(n==='+1d6 dano'){extraDie++;total+=[2,3,4][Math.min(extraDie-1,2)]}else total+=u.cost});(p.limitations||[]).forEach(n=>total+=(D.limitations.find(x=>x.name===n)?.cost||0));total=Math.max(1,total);if(p.signature&&hasTalent('poder_assinatura'))total=Math.max(1,total-1);if(state.level>=10&&state.capstone==='mestre_arcano'&&String(state.masterArcanePowerId)===String(p.id)&&p.tier==='Avançado')total=Math.max(1,total-3);return total}
function powerWarnings(p){const tier=D.powerTiers[p.tier]||D.powerTiers.Comum,cost=powerCost(p),w=[];if(cost<tier.min||cost>tier.max)w.push(`Custo ${cost} fora da faixa ${tier.min}–${tier.max}.`);if(state.level<tier.level)w.push(`Requer nível ${tier.level}.`);if(p.tier==='Supremo')w.push('Poder Supremo: efeito único, grande área ou alteração de cena; exige aprovação do mestre.');else{if((p.damage||[]).length>tier.damage)w.push(`Estrutura recomendada: até ${tier.damage} tipo(s) de dano.`);if((p.effects||[]).length>tier.effect)w.push(`Estrutura recomendada: até ${tier.effect} efeito(s).`);if((p.upgrades||[]).length>tier.upgrade)w.push(`Estrutura recomendada: até ${tier.upgrade} melhoria(s).`)}if(p.tier==='Comum'&&(p.upgrades||[]).length)w.push('Poder Comum recomenda nenhuma melhoria complexa.');return w}
function optionList(items,value,key='name'){return '<option value="">—</option>'+items.map(x=>{const v=x[key];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`}).join('')}
function renderPowerRows(p,kind,items,key){return (p[kind]||[]).map((v,i)=>{const item=items.find(x=>x[key]===v);const info=kind==='damage'?`${item?.die||''} · ${item?.natural||''} · ${item?.cost?`+${item.cost}`:'base'}`:kind==='effects'?`${item?.duration||''} · ${item?.effect||''} · +${item?.cost||0}`:kind==='limitations'?`Redução de ${Math.abs(item?.cost||0)} PE`:`${item?.effect||''} · ${item?.cost>=0?'+':''}${item?.cost||0}`;return `<div class="power-row"><select class="control" data-power-id="${p.id}" data-power-array="${kind}" data-index="${i}">${optionList(items,v,key)}</select><span class="power-info">${esc(info)}</span><button class="btn btn-danger btn-icon no-print" data-power-remove-row="${kind}" data-power-id="${p.id}" data-index="${i}">×</button></div>`}).join('')}
function renderPowers(){$('powers-list').innerHTML=state.powers.map(p=>{const cost=powerCost(p),warnings=powerWarnings(p),tier=D.powerTiers[p.tier]||D.powerTiers.Comum;return `<article class="power-card"><div class="power-head"><div class="field wide"><label>Nome</label><input data-power-id="${p.id}" data-power-field="name" value="${esc(p.name)}"></div><div class="field"><label>Fonte</label><select data-power-id="${p.id}" data-power-field="source">${['Arcano','Divino','Abissal','Técnico'].map(v=>`<option ${p.source===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Categoria</label><select data-power-id="${p.id}" data-power-field="tier">${Object.keys(D.powerTiers).map(v=>`<option ${p.tier===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="cost-badge">Custo<strong>${cost}</strong>PE</div><button class="btn btn-danger btn-icon no-print" data-remove-power="${p.id}">×</button></div><div class="grid grid-4"><div class="field"><label>Atributo-chave</label><select data-power-id="${p.id}" data-power-field="keyAttr">${D.attributes.map(a=>`<option value="${a}" ${p.keyAttr===a?'selected':''}>${D.attributeLabels[a]}</option>`).join('')}</select></div><div class="field"><label>Perícia de ativação</label><select data-power-id="${p.id}" data-power-field="skill">${ALL_SKILLS.map(s=>`<option ${p.skill===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Forma</label><select data-power-id="${p.id}" data-power-field="form">${D.powerForms.map(f=>`<option ${p.form===f.name?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><label class="check-card"><input type="checkbox" data-power-id="${p.id}" data-power-field="signature" ${p.signature?'checked':''}><span><span class="name">Poder Assinatura</span><span class="desc">Somente um poder pode receber -1 PE.</span></span></label></div><div class="power-section"><div class="power-section-title">Tipos de dano (${(p.damage||[]).length}/${p.tier==='Supremo'?'estrutura especial':tier.damage+' recomendado'})</div>${renderPowerRows(p,'damage',D.damageTypes,'name')}<button class="btn btn-small no-print" data-power-add="damage" data-power-id="${p.id}">+ dano</button></div><div class="power-section"><div class="power-section-title">Efeitos (${(p.effects||[]).length}/${p.tier==='Supremo'?'estrutura especial':tier.effect+' recomendado'})</div>${renderPowerRows(p,'effects',D.debuffs,'name')}<button class="btn btn-small no-print" data-power-add="effects" data-power-id="${p.id}">+ efeito</button></div><div class="power-section"><div class="power-section-title">Melhorias (${(p.upgrades||[]).length}/${p.tier==='Supremo'?'estrutura especial':tier.upgrade+' recomendado'})</div>${renderPowerRows(p,'upgrades',D.upgrades,'name')}<button class="btn btn-small no-print" data-power-add="upgrades" data-power-id="${p.id}">+ melhoria</button></div><div class="power-section"><div class="power-section-title">Limitações</div>${renderPowerRows(p,'limitations',D.limitations,'name')}<button class="btn btn-small no-print" data-power-add="limitations" data-power-id="${p.id}">+ limitação</button></div><div class="field"><label>Descrição</label><textarea data-power-id="${p.id}" data-power-field="description">${esc(p.description||'')}</textarea></div><div class="power-warning ${warnings.length?'':'power-ok'}">${warnings.length?esc(warnings.join(' ')):`Válido como ${esc(p.tier)}. DT de Poder: ${10+(state.attrs[p.keyAttr]||0)+effectiveTraining(p.skill)+Math.floor(state.level/2)}.`}</div></article>`}).join('');bindPowerEvents();renderTalentOptions()}
function findPower(id){return state.powers.find(p=>String(p.id)===String(id))}
function bindPowerEvents(){qsa('[data-power-field]').forEach(el=>{const field=el.dataset.powerField,event=(el.type==='checkbox'||el.tagName==='SELECT')?'change':'input';el.addEventListener(event,e=>{const p=findPower(e.target.dataset.powerId);if(!p)return;if(field==='signature'&&e.target.checked){state.powers.forEach(x=>x.signature=String(x.id)===String(p.id))}else p[field]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(['tier','form','keyAttr','skill','signature','source'].includes(field))renderPowers();renderValidation()})});qsa('[data-power-array]').forEach(el=>el.addEventListener('change',e=>{const p=findPower(e.target.dataset.powerId);if(!p)return;p[e.target.dataset.powerArray][Number(e.target.dataset.index)]=e.target.value;renderPowers()}));qsa('[data-power-add]').forEach(b=>b.addEventListener('click',e=>{const p=findPower(e.target.dataset.powerId),k=e.target.dataset.powerAdd;if(!p)return;p[k]=p[k]||[];p[k].push('');renderPowers()}));qsa('[data-power-remove-row]').forEach(b=>b.addEventListener('click',e=>{const p=findPower(e.target.dataset.powerId);if(!p)return;p[e.target.dataset.powerRemoveRow].splice(Number(e.target.dataset.index),1);renderPowers()}));qsa('[data-remove-power]').forEach(b=>b.addEventListener('click',e=>{state.powers=state.powers.filter(p=>String(p.id)!==String(e.target.dataset.removePower));renderPowers();renderValidation()}))}
function renderEquipment(){const a=armor(),w=weapon(),trained=armorTrainedForCurrent(),stealth=trained&&a.stealth!=='Nenhuma'?`${a.stealth} (ignorada por Armadura Treinada)`:a.stealth;$('armor-info').innerHTML=`<strong>${esc(a.name)}</strong><br>+${a.defense} Defesa · ${esc(stealth)}${a.strength?` · Exige Força ${a.strength}`:''}${a.strength>state.attrs.forca?'<br><span class="tag tag-red">Força insuficiente — o talento não remove o requisito.</span>':''}`;$('weapon-info').innerHTML=`<strong>${esc(w.name)}</strong><br>${esc(w.damage)} · ${esc(w.property)}<br>${esc(w.notes)}`;$('slots-capacity').textContent=inventoryCapacity();$('encumbrance-info').textContent=isEncumbered()?'Sobrecarregado: Movimento -2m e desvantagem em Atletismo e Acrobacia.':'Carga dentro do limite.';renderConsumables()}
function renderConsumables(){qsa('[data-consumable]').forEach(cb=>{cb.checked=state.consumables.includes(cb.dataset.consumable);cb.closest('.check-card').classList.toggle('active',cb.checked)})}function renderConditions(){qsa('[data-condition]').forEach(cb=>{cb.checked=state.conditions.includes(cb.dataset.condition);cb.closest('.check-card').classList.toggle('active',cb.checked)})}function renderDeathTracks(){qsa('[data-death="success"]').forEach(b=>b.classList.toggle('active',Number(b.dataset.value)<=state.deathSuccess));qsa('[data-death="fail"]').forEach(b=>b.classList.toggle('active',Number(b.dataset.value)<=state.deathFail))}
function renderReputation(){$('reputation-list').innerHTML=(state.reputation||[]).map((r,i)=>`<div class="reputation-row"><input class="control" data-rep-index="${i}" data-rep-field="name" value="${esc(r.name||'')}" placeholder="Região, culto ou facção"><select class="control" data-rep-index="${i}" data-rep-field="value">${[-3,-2,-1,0,1,2,3].map(v=>`<option value="${v}" ${Number(r.value)===v?'selected':''}>${v>0?'+':''}${v}</option>`).join('')}</select><button class="btn btn-danger btn-icon no-print" data-remove-rep="${i}">×</button></div>`).join('')||'<div class="section-note">Nenhuma reputação registrada.</div>';qsa('[data-rep-field]').forEach(el=>el.addEventListener('input',e=>{const r=state.reputation[Number(e.target.dataset.repIndex)];r[e.target.dataset.repField]=e.target.dataset.repField==='value'?Number(e.target.value):e.target.value}));qsa('[data-remove-rep]').forEach(b=>b.addEventListener('click',e=>{state.reputation.splice(Number(e.target.dataset.removeRep),1);renderReputation()}))}
function renderAvatar(){const has=Boolean(state.avatarData);['avatar-preview','current-avatar'].forEach(id=>{const im=$(id);im.classList.toggle('hidden',!has);if(has)im.src=state.avatarData});$('avatar-placeholder').classList.toggle('hidden',has);$('current-avatar-placeholder').classList.toggle('hidden',has);$('avatar-remove-btn').classList.toggle('hidden',!has)}
function handleAvatarUpload(e){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){setStatus('Escolha uma imagem válida.',true);return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=360,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);state.avatarData=canvas.toDataURL('image/jpeg',.84);renderAvatar();renderCharacterSummary()};img.src=reader.result};reader.readAsDataURL(file);e.target.value=''}
function renderCharacterSummary(){const name=$('f-nome').value.trim()||'Nova ficha',parts=[];if(state.race)parts.push(D.races[state.race]?.label||state.race);if(state.profession)parts.push(state.profession);parts.push(`Nível ${state.level}`);$('current-character-name').textContent=name;$('current-character-meta').textContent=currentSheetId?parts.join(' · '):`${parts.join(' · ')} · ainda não salva`;if(!$('save-name').value&&$('f-nome').value)$('save-name').value=$('f-nome').value}
function validationItem(ok,title,detail,warn=false){return `<div class="validation-item ${ok?'ok':warn?'warn':''}"><span class="validation-icon">${ok?'✓':warn?'!':'·'}</span><div><strong>${esc(title)}</strong><span>${esc(detail)}</span></div></div>`}
function renderValidation(){const items=[];const identity=Boolean($('f-nome').value.trim()&&$('f-regiao').value&&$('f-conceito').value.trim()&&$('f-objetivo').value.trim()&&$('f-vinculo').value.trim());items.push(validationItem(identity,'Conceito e vínculos',identity?'Base narrativa preenchida.':'Preencha nome, região, conceito, objetivo e vínculo.'));items.push(validationItem(Boolean(state.race),'Raça',state.race?(D.races[state.race]?.label||state.race):'Escolha uma raça jogável.'));items.push(validationItem(Boolean(state.profession),'Profissão',state.profession||'Escolha uma das 12 profissões oficiais.'));items.push(validationItem(attrSpent()===attrPool(),'Atributos',`${attrSpent()} / ${attrPool()} pontos distribuídos.`,attrSpent()!==attrPool()));items.push(validationItem(trainingSpent()<=trainingPool(),'Treino',`${trainingSpent()} / ${trainingPool()} pontos usados.`,trainingSpent()>trainingPool()));items.push(validationItem(Boolean(state.path),'Caminho espiritual',state.path||'Escolha Devoto, Livre ou Pactuário.'));items.push(validationItem(state.talents.length<=talentSlots(),'Talentos',`${state.talents.length} / ${talentSlots()} espaço(s) usados.`,state.talents.length>talentSlots()));
  if(state.path==='Devoto'){const g=D.blessings[state.patron],learned=(g?.skills||[]).filter(s=>state.learnedBlessings.includes(s.nome)),okFavor=state.level>1||state.favor===2,ok=Boolean(state.patron)&&okFavor&&(state.level>1||learned.length===2&&learned.every(s=>s.custo<=5));items.push(validationItem(ok,'Início Devoto',state.level>1?'Patrono e progressão registrados.':`Favor ${state.favor}; ${learned.length}/2 bênçãos de custo até 5.`,!ok))}
  if(state.path==='Livre'){const common=state.powers.filter(p=>p.tier==='Comum').length,ok=state.level>1||common===2;items.push(validationItem(ok,'Início Livre',state.level>1?'Progressão do Caminho Livre ativa.':`${common}/2 poderes Comuns; talento adicional liberado.`,!ok))}
  if(state.path==='Pactuário'){const ab=state.powers.filter(p=>p.source==='Abissal').length,ok=(state.level>1?state.corruption>=1:state.corruption===1)&&Boolean(state.pactType)&&Boolean($('p-marca').value.trim())&&(state.level>1||ab===1);items.push(validationItem(ok,'Início Pactuário',`Corrupção ${state.corruption}; pacto ${state.pactType?'definido':'não definido'}; ${ab} poder(es) abissal(is).`,!ok))}
  const equipOk=armor().strength<=state.attrs.forca;items.push(validationItem(equipOk,'Equipamento',equipOk?`Carga ${state.slotsUsed}/${inventoryCapacity()} espaços.`:`${state.armor} exige Força ${armor().strength}.`,!equipOk));const allOk=items.every(x=>x.includes('validation-item ok'));$('grimorio-validation').innerHTML=items.join('');$('validation-seal').textContent=allOk?'Conforme':'Em criação';$('validation-seal').className=`seal-badge ${allOk?'ok':'warn'}`}

const FORM_FIELDS=['f-nome','f-jogador','f-regiao','f-origem','f-conceito','f-objetivo','f-medo','f-vinculo','f-divida','f-verdade','f-prof-upgrade','f-level-choice','f-dogma','f-divine-corruption','f-milagre','p-entidade','p-desejo','p-dadiva','p-preco','p-marca','p-clausula','f-inventario','f-reliquias','f-ferimentos','f-efeitos-continuos','f-favores','f-dividas-faccao','f-historia','f-notas'];
function buildSheetData(){state.corruptionManifestation=$('f-corruption-manifestation').value;state.corruptionPenalty=$('f-corruption-penalty').value;const fields={};FORM_FIELDS.forEach(id=>fields[id]=$(id).value);return {schemaVersion:3,fields,state:JSON.parse(JSON.stringify(state)),savedAt:new Date().toISOString()}}
function applySheetData(raw){const data=migrateData(raw||{});state=data.state;FORM_FIELDS.forEach(id=>$(id).value=data.fields?.[id]||'');renderAll();if(migrationNotice)setStatus(migrationNotice,false)}
function migrateData(raw){migrationNotice='';if([2,3].includes(raw.schemaVersion)||[2,3].includes(raw.state?.schemaVersion)){const base=defaultState(),old=raw.state||{},s={...base,...old};s.schemaVersion=3;s.attrs={...base.attrs,...old.attrs};s.training={...base.training,...old.training};s.talents=Array.isArray(s.talents)?s.talents:[];if(s.talents.includes('critico_fisico')||s.talents.includes('critico_magico')){s.criticalChoice=s.talents.includes('critico_magico')?'magico':'fisico';s.talents=s.talents.filter(x=>!['critico_fisico','critico_magico'].includes(x));if(!s.talents.includes('critico_aprimorado'))s.talents.push('critico_aprimorado')}s.profession=officialProfessionFromLegacy(s.profession);s.powers=Array.isArray(s.powers)?s.powers:[];s.learnedBlessings=Array.isArray(s.learnedBlessings)?s.learnedBlessings:[];s.reputation=Array.isArray(s.reputation)?s.reputation:[];if(raw.schemaVersion===2||old.schemaVersion===2)migrationNotice='Ficha v2 migrada: profissões regionais foram convertidas para a profissão-base oficial e Crítico Aprimorado foi unificado conforme o Grimório.';return {schemaVersion:3,fields:raw.fields||{},state:s}}
  const old=raw.state||{},s=defaultState();s.level=clamp(Number(old.level)||1,1,10);D.attributes.forEach(a=>s.attrs[a]=Math.max(1,Number(old.attrs?.[a])||1));s.race=old.race||'';s.profession=officialProfessionFromLegacy(old.profession||'');s.pvLoss=Number(old.pvOffset)||0;s.peSpent=Number(old.peOffset)||0;s.soulLoss=Number(old.soulOffset)||0;s.corruption=Number(old.corruption)||0;Object.keys(s.training).forEach(k=>s.training[k]=Number(old.training?.[k])||0);const oldGod=raw.blessings?.[0]?.deus||raw.identity?.deus||'';if(D.blessings[oldGod]){s.patron=oldGod;s.path='Devoto';s.learnedBlessings=D.blessings[oldGod].skills.map(x=>x.nome)}s.powers=(raw.powers||[]).map(p=>({id:String(Date.now()+Math.random()),name:p.nome||'',source:'Arcano',tier:p.tier||'Comum',keyAttr:'intelecto',skill:'Ocultismo',form:'Ataque direto',damage:(p.danos||[]).map(x=>x.tipo).filter(Boolean),effects:(p.efeitos||[]).map(x=>x.nome==='Corrupção'?'Ruína da Alma':x.nome).filter(Boolean),upgrades:(p.melhorias||[]).map(x=>x.nome).filter(Boolean),limitations:[],description:p.descricao||'',signature:false}));const f={'f-nome':raw.identity?.nome||'','f-jogador':raw.identity?.jogador||'','f-regiao':raw.identity?.regiao||'','f-objetivo':raw.identity?.promessa||'','f-inventario':raw.inventario||'','f-notas':raw.notas||''};migrationNotice='Ficha antiga migrada para a Edição Expandida. Revise atributos, profissão e bênçãos.';return {schemaVersion:3,fields:f,state:s}}

async function api(path,options={}){const opts={...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};const res=await fetch(path,opts),data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Erro na requisição');return data}
async function checkSession(){try{const me=await api('/api/me');showApp(me.username,me.isAdmin)}catch{$('auth-overlay').classList.remove('hidden');$('app-content').classList.add('hidden')}}
function showApp(username,isAdmin){$('auth-overlay').classList.add('hidden');$('app-content').classList.remove('hidden');$('whoami').textContent=username;$('master-toggle-btn').classList.toggle('hidden',!isAdmin);refreshSheetDropdown(null,true)}
async function doLogin(){setAuthStatus('');try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({username:$('auth-username').value.trim(),password:$('auth-password').value})});showApp(r.username,r.isAdmin)}catch(e){setAuthStatus(e.message,true)}}
async function doRegister(){setAuthStatus('');try{const r=await api('/api/register',{method:'POST',body:JSON.stringify({username:$('auth-username').value.trim(),password:$('auth-password').value})});showApp(r.username,r.isAdmin)}catch(e){setAuthStatus(e.message,true)}}
async function doLogout(){await api('/api/logout',{method:'POST'});currentSheetId=null;$('app-content').classList.add('hidden');$('auth-overlay').classList.remove('hidden')}
function setAuthStatus(msg,error=false){$('auth-status').textContent=msg;$('auth-status').className=`status-msg ${error?'error':''}`}function setStatus(msg,error=false){$('save-status').textContent=msg;$('save-status').className=`status-msg toolbar-status ${error?'error':'success'}`}
async function refreshSheetDropdown(selectId,openAfter=false){try{sheetRows=await api('/api/sheets');$('sheet-select').innerHTML=sheetRows.length?'':'<option value="">— nenhuma salva —</option>';sheetRows.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.name;$('sheet-select').appendChild(o)});if(selectId)$('sheet-select').value=selectId;renderCharacterCards();if(openAfter)$('character-library').classList.remove('hidden')}catch{$('sheet-select').innerHTML='<option value="">— indisponível —</option>';sheetRows=[];renderCharacterCards()}}
function renderCharacterCards(){$('character-cards').innerHTML=sheetRows.map(r=>{const s=r.summary||{},avatar=s.avatar||'',raceLabel=D.races[s.race]?.label||s.race||'Raça não definida';return `<article class="character-card" data-open-sheet="${r.id}"><div class="character-card-avatar">${avatar?`<img src="${avatar}" alt="">`:'✦'}</div><div><strong>${esc(r.name)}</strong><small>${esc(raceLabel)} · ${esc(s.profession||'Sem profissão')} · Nível ${esc(s.level||1)}</small><small>${esc(s.region||'Origem não definida')} · ${new Date(r.updated_at).toLocaleDateString('pt-BR')}</small><div class="card-actions"><button class="btn btn-small" data-card-load="${r.id}">Abrir</button><button class="btn btn-small btn-danger" data-card-delete="${r.id}">Excluir</button></div></div></article>`}).join('')||'<div class="section-note">Nenhuma ficha salva ainda.</div>';qsa('[data-card-load]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();loadSheetById(b.dataset.cardLoad)}));qsa('[data-open-sheet]').forEach(c=>c.addEventListener('click',()=>loadSheetById(c.dataset.openSheet)));qsa('[data-card-delete]').forEach(b=>b.addEventListener('click',async e=>{e.stopPropagation();$('sheet-select').value=b.dataset.cardDelete;await deleteSelectedSheet()}))}
async function saveCurrentSheet(){let name=$('save-name').value.trim()||$('f-nome').value.trim();if(!name){setStatus('Informe o nome do personagem antes de salvar.',true);return}try{const data=buildSheetData();if(currentSheetId)await api(`/api/sheets/${currentSheetId}`,{method:'PUT',body:JSON.stringify({name,data})});else{const r=await api('/api/sheets',{method:'POST',body:JSON.stringify({name,data})});currentSheetId=r.id}await refreshSheetDropdown(currentSheetId);renderCharacterSummary();setStatus(`Ficha “${name}” salva.`)}catch(e){setStatus(e.message,true)}}
async function loadSheetById(id){try{const r=await api(`/api/sheets/${id}`);applySheetData(r.data);currentSheetId=r.id;$('save-name').value=r.name;$('sheet-select').value=r.id;closeLibrary();switchTab('sheet');renderCharacterSummary();setStatus(`Ficha “${r.name}” carregada.`)}catch(e){setStatus(e.message,true)}}
async function loadSelectedSheet(){const id=$('sheet-select').value;if(!id){setStatus('Selecione uma ficha.',true);return}return loadSheetById(id)}
async function deleteSelectedSheet(){const id=$('sheet-select').value;if(!id){setStatus('Selecione uma ficha.',true);return}if(!confirm('Excluir esta ficha?'))return;try{await api(`/api/sheets/${id}`,{method:'DELETE'});if(String(currentSheetId)===String(id)){currentSheetId=null;$('save-name').value=''}await refreshSheetDropdown();renderCharacterSummary();setStatus('Ficha excluída.')}catch(e){setStatus(e.message,true)}}
function newSheet(){currentSheetId=null;$('save-name').value='';applySheetData({schemaVersion:3,fields:{},state:defaultState()});switchTab('sheet');setStatus('Nova ficha iniciada. Comece pelo conceito do personagem.')}
function exportSheet(){const blob=new Blob([JSON.stringify(buildSheetData(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aetheris_${($('f-nome').value||'ficha').replace(/[^a-z0-9]+/gi,'_')}_v3.json`;a.click();URL.revokeObjectURL(url);setStatus('Ficha exportada.')}
function importSheet(e){const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{applySheetData(JSON.parse(r.result));currentSheetId=null;$('save-name').value=$('f-nome').value;setStatus('Ficha importada. Salve para criar um novo registro.')}catch{setStatus('Arquivo inválido.',true)}};r.readAsText(file);e.target.value=''}
async function toggleMasterPanel(){const opening=$('master-panel').classList.contains('hidden');$('master-panel').classList.toggle('hidden',!opening);if(opening)await loadMasterList()}
async function loadMasterList(){const body=$('master-body');body.innerHTML='<tr><td colspan="4">Carregando…</td></tr>';try{const rows=await api('/api/admin/sheets');body.innerHTML=rows.map(r=>`<tr><td>${esc(r.username)}</td><td>${esc(r.name)}</td><td>${esc(new Date(r.updated_at).toLocaleString('pt-BR'))}</td><td><button class="btn btn-small" data-master-view="${r.id}" data-user="${esc(r.username)}" data-name="${esc(r.name)}">Ver</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma ficha.</td></tr>';qsa('[data-master-view]').forEach(b=>b.addEventListener('click',()=>viewPlayerSheet(b.dataset.masterView,b.dataset.user,b.dataset.name)))}catch(e){body.innerHTML=`<tr><td colspan="4">${esc(e.message)}</td></tr>`}}
async function viewPlayerSheet(id,user,name){try{const r=await api(`/api/admin/sheets/${id}`);applySheetData(r.data);masterViewing=true;$('master-view-who').textContent=`${user} — “${name}”`;$('master-view-banner').classList.remove('hidden');setFormDisabled(true);$('master-view-banner').scrollIntoView({behavior:'smooth'})}catch(e){setStatus(e.message,true)}}
function exitMasterView(){masterViewing=false;$('master-view-banner').classList.add('hidden');setFormDisabled(false);newSheet()}function setFormDisabled(disabled){qsa('#app-content input,#app-content select,#app-content textarea,#app-content button').forEach(el=>{if(el.closest('#master-panel')||el.closest('#master-view-banner')||el.closest('.header')||el.closest('.book-tabs')||el.closest('footer'))return;el.disabled=disabled})}

initStatic();
